export function MessageComposer({
  placeholder = "{{placeholder}}",
  draft = "{{draft}}",
  variant = "{{variant}}",
  attachEnabled = {{attachEnabled}},
  charLimit = {{charLimit}},
}) {
  const pad = { compact: 8, expanded: 20, threaded: 16 }[variant] ?? 16;
  const border = variant === "threaded" ? "3px solid #A8E6C1" : "1px solid #24143026";
  return (
    <form style={{ font: "14px/1.5 system-ui, sans-serif", maxWidth: 420, boxSizing: "border-box",
      background: "#FAF7F2", color: "#241430", borderRadius: 12, padding: pad,
      borderLeft: variant === "threaded" ? border : undefined,
      border: variant === "threaded" ? undefined : border }}>
      <label htmlFor="mc-input" style={{ display: "block", fontWeight: 600, marginBottom: 6, fontSize: 13 }}>Message</label>
      <textarea id="mc-input" rows={3} placeholder={placeholder} defaultValue={draft}
        style={{ width: "100%", boxSizing: "border-box", font: "inherit", border: "1px solid #24143033",
          borderRadius: 8, padding: 10, background: "#fff", color: "#241430" }} />
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginTop: 10 }}>
        {attachEnabled && (
          <button type="button" aria-label="Attach file" style={{ border: "none", background: "transparent", color: "#241430", cursor: "pointer", padding: 6, borderRadius: 6, display: "inline-flex" }}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true"><path d="M7 12v6a3 3 0 0 0 6 0V8a5 5 0 0 0-10 0v9a7 7 0 0 0 14 0V10" /></svg>
          </button>
        )}
        <span style={{ fontSize: 12, color: "#24143099", flex: 1 }}>{charLimit} character limit</span>
        <button type="button" style={{ marginLeft: "auto", background: "#241430", color: "#FAF7F2", border: "none", borderRadius: 8, padding: "8px 16px", fontSize: 13, fontWeight: 600, cursor: "pointer" }}>Send</button>
      </div>
    </form>
  );
}
